  "selectedAngle": "The readonly shopping trip",
  "title": "The Read-Only Shopping Trip",
  "scenes": [
    {
      "id": "hook",
      "turns": [
        {
          "speakerId": "alex",
          "text": "The cart expected read-only."
        }
      ],
      "screenText": "Read-only? Really?",
      "visualBeat": "Close-up of readonly annotation on inventory service.",
      "factIds": ["d1"]
    },
    {
      "id": "context",
      "turns": [
        {
          "speakerId": "sam",
          "text": "I expected add-to-cart to create a purchase."
        },
        {
          "speakerId": "alex",
          "text": "The checked create request got HTTP 405."
        },
        {
          "speakerId": "sam",
          "text": "So writes are blocked here?"
        },
        {
          "speakerId": "alex",
          "text": "For this readonly projection, yes. The cart has no keys."
        }
      ],
      "screenText": "Expected create. Actual 405.",
      "visualBeat": "Illustration: split screen of cart icon and HTTP 405 response.",
      "factIds": ["d2"]
    },
    {
      "id": "beat-1",
      "turns": [
        {
          "speakerId": "sam",
          "text": "Does the local service allow queries?"
        },
        {
          "speakerId": "alex",
          "text": "It allows queries and rejects that checked create."
        },
        {
          "speakerId": "sam",
          "text": "Not every write, just this readonly projection?"
        },
        {
          "speakerId": "alex",
          "text": "The monitor arm asked to join. Stock said no."
        }
      ],
      "screenText": "Queries allowed. Create rejected.",
      "visualBeat": "Code editor shows readonly projection; request line changes to blocked.",
      "factIds": ["d1", "d2"]
    },
