      "id": "beat-2",
      "turns": [
        {
          "speakerId": "sam",
          "text": "What stock-above-zero query returns?"
        },
        {
          "speakerId": "alex",
          "text": "Keyboard and dock returned; monitor arm did not."
        }
      ],
      "screenText": "Stock above zero: two rows.",
      "visualBeat": "Query result changes from empty to keyboard and dock.",
      "factIds": ["d3", "d4"]
    },
    {
      "id": "beat-3",
      "turns": [
        {
          "speakerId": "sam",
          "text": "Clearing the filter returned all three rows?"
        },
        {
          "speakerId": "alex",
          "text": "Yes, and stock zero explained the monitor arm."
        }
      ],
      "screenText": "Clear filter: all three rows.",
      "visualBeat": "Result grid expands to all three rows.",
      "factIds": ["d3", "d4"]
    },
    {
      "id": "payoff",
      "turns": [
        {
          "speakerId": "alex",
          "text": "The readonly projection stopped create, not all writes."
        },
        {
          "speakerId": "sam",
          "text": "This local prototype is not production."
        },
        {
          "speakerId": "alex",
          "text": "Production auth and deployment are separate."
        }
      ],
      "screenText": "Readonly scope: local prototype.",
      "visualBeat": "Annotation: production auth separate from local demo.",
      "factIds": ["d2", "d5"]
    },
    {
      "id": "cta",
      "turns": [
        {
          "speakerId": "sam",
          "text": "Run npm run demo and inspect Products."
        },
        {
          "speakerId": "alex",
          "text": "Then ask your own readonly questions."
        },
        {
          "speakerId": "sam",
          "text": "No real purchase is being made."
        }
      ],
      "screenText": "Run npm run demo. Ask next.",
      "visualBeat": "Terminal starts prepared inventory project; Products endpoint opens.",
      "factIds": ["d4", "d5"]
